import{_ as t,o,c as a,ae as s}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Troubleshooting local development","description":"","frontmatter":{},"headers":[],"relativePath":"guides/troubleshooting-local-dev.md","filePath":"guides/troubleshooting-local-dev.md"}'),r={name:"guides/troubleshooting-local-dev.md"};function n(l,e,c,i,d,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting-local-development" tabindex="-1">Troubleshooting local development <a class="header-anchor" href="#troubleshooting-local-development" aria-label="Permalink to &quot;Troubleshooting local development&quot;">​</a></h1><p>Short fixes for common issues when working on this repo locally.</p><h2 id="enospc-disk-full" tabindex="-1">ENOSPC / disk full <a class="header-anchor" href="#enospc-disk-full" aria-label="Permalink to &quot;ENOSPC / disk full&quot;">​</a></h2><p>If builds or tests fail with <strong>ENOSPC</strong> or the disk is nearly full, free space and clear transient caches:</p><ul><li><strong>Project <code>.tmp</code></strong> — Remove or trim contents under the repo’s <code>.tmp</code> directory when safe (it holds scratch and generated artifacts).</li><li><strong>Bun package cache</strong> — Run <code>bun pm cache rm</code> (or clear Bun’s global cache location for your install) to reclaim space from cached packages.</li><li><strong><code>apps/runtime</code> test scratch</strong> — Runtime tests may write under <code>apps/runtime</code>; clean any leftover test output or temp dirs there after failed runs.</li></ul><p>Then retry the command that failed.</p><h2 id="bun-version" tabindex="-1">Bun version <a class="header-anchor" href="#bun-version" aria-label="Permalink to &quot;Bun version&quot;">​</a></h2><p>CI and local tooling expect the Bun version pinned in <code>package.json</code> (<code>packageManager</code>, e.g. <code>bun@1.2.20</code>). Install that exact version (for example via <a href="https://bun.sh/docs/installation" target="_blank" rel="noreferrer">Bun’s install docs</a>) so scripts and tests behave the same as in automation.</p><h2 id="secrets-tests" tabindex="-1">Secrets tests <a class="header-anchor" href="#secrets-tests" aria-label="Permalink to &quot;Secrets tests&quot;">​</a></h2><p>Secrets-related tests may use files under <strong><code>.tmp/runtime-secrets-tests</code></strong>. That path is for local scratch only: <strong>do not commit</strong> it or add real secrets; keep it gitignored and delete when done testing.</p>',10)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
